class Shape
    public method Area() as real
        return 0.0;
    endMethod
endClass

class Square extends Shape
    private define side as integer;

    method constructor(aSide as integer)
        this.side <- aSide;
    endMethod

    public method Area() as real
        return this.side * this.side;
    endMethod
endClass

class Circle extends Shape
    private define radius as integer;

    method constructor(aRadius as integer)
        this.radius <- aRadius;
    endMethod

    public method Area() as real
        return this.radius * this.radius * 3.14;
    endMethod
endClass

algorithm SumAreas
    dimension shapes[2] as Shape;
    define side as integer;
    define radius as integer;
    define i as integer;
    define total as real;
    read side;
    read radius;
    shapes[0] <- new Square(side);
    shapes[1] <- new Circle(radius);
    total <- 0.0;
    for i <- 0 to 1 step 1 do
        total <- total + shapes[i].Area();
    endFor
    write total;
endAlgorithm
